# What the server says about a skating rider: a short ride, then skate.status, the server's speed
# checks and its plugin list typed into the F1 console, which stays open for screenshots.
# Joins the private test server at start; press a key to wake the player.
$global:ptag='S'; $global:psteps='mute,status'; $global:pdone=1800; $global:psteam=$false; $global:pconnect=$true; $global:pkeep=$true; $global:plisten=$false; $global:prt="$HOME\Downloads\claude-loader-probe\rt"; $global:pplug="$HOME\Downloads\claude-loader-probe\plugin"; $global:pwait=30; $global:ppreload=$false; $global:ptail=4
$global:pnext='session'; zz build
